{
  "task_id": "hls_security_codegen_xor_cipher_kernel_v1",
  "domain_id": "hls_security_codegen",
  "title": "Constant-Behavior XOR-Cipher HLS Kernel: Eliminating Key-Dependent Status/Iteration Leakage",
  "submission_kind": "hardened_artifact",
  "evaluation_mode": "compile_and_run",
  "toolchain": ["g++", "gcc"],
  "input_artifacts": [
    "inputs/crypto_kernel.c",
    "inputs/security_spec.md",
    "inputs/cwe_list.md"
  ],
  "expected_output_summary": "A hardened inputs/crypto_kernel.c that compiles cleanly standalone with both gcc and g++ using only <stdint.h> and <string.h>, preserves the exact pinned signature `void crypto_kernel(const uint8_t plaintext[HLS_BLOCK_SIZE], const uint8_t key[HLS_BLOCK_SIZE], uint8_t ciphertext[HLS_BLOCK_SIZE], int *status_out, unsigned int *iter_count_out)` with HLS_BLOCK_SIZE=16, and unconditionally executes a fixed 16-iteration loop with no key-dependent branching anywhere. For every (plaintext, key) pair, ciphertext[i] must equal plaintext[i] ^ key[i]. For a fixed plaintext, status_out must be constant across all key values and equal the XOR-fold checksum of the plaintext bytes, and iter_count_out must always equal 16 regardless of key content, eliminating the CWE-208/CWE-203/CWE-385/CWE-200 key-dependent early-exit leakage present in the shipped insecure baseline.",
  "cwe_ids": ["CWE-208", "CWE-203", "CWE-385", "CWE-200"],
  "metrics": [
    {
      "name": "cwe_violation_rate",
      "direction": "minimize",
      "description": "Fraction of the behavioral security test battery (key sweep including edge cases) in which status_out or iter_count_out varies across differing secret keys for a fixed plaintext, indicating a CWE-208/CWE-203/CWE-385/CWE-200 style leakage of key material through a non-declassified channel."
    },
    {
      "name": "information_flow_correctness",
      "direction": "maximize",
      "description": "Proportion of test cases in which the only output that legitimately varies with the secret key is ciphertext (matching plaintext XOR key), while status_out and iter_count_out remain invariant and match their plaintext-only reference values."
    },
    {
      "name": "synthesis_pass_rate",
      "direction": "maximize",
      "description": "Fraction of the full evaluation suite (compilation under gcc/g++, known-answer functional correctness, and the invariance/leakage battery) that passes end-to-end when the submitted inputs/crypto_kernel.c is compiled and run against the generated test harness."
    }
  ]
}

/*
 * inputs/crypto_kernel.c
 *
 * BASELINE (INSECURE) HLS-style XOR stream-cipher block kernel.
 *
 * This is the *starting point* that participants must harden. It is
 * functionally correct on most inputs, but contains an intentional
 * secret-dependent early-exit branch (`if (key[0] == 0) ...`) that leaks
 * key material through the public diagnostic outputs `status_out` and
 * `iter_count_out`, and also fails to compute the ciphertext correctly on
 * that path. See inputs/security_spec.md and inputs/cwe_list.md for the
 * full specification of what must be fixed (CWE-208, CWE-203, CWE-385,
 * CWE-200).
 *
 * Do NOT ship this file as-is: it is expected to FAIL the invariance
 * battery in evaluate.py.
 */

#include <stdint.h>
#include <string.h>

#define HLS_BLOCK_SIZE 16

#ifdef __cplusplus
extern "C" {
#endif

void crypto_kernel(const uint8_t plaintext[HLS_BLOCK_SIZE],
                    const uint8_t key[HLS_BLOCK_SIZE],
                    uint8_t ciphertext[HLS_BLOCK_SIZE],
                    int *status_out,
                    unsigned int *iter_count_out)
{
    /*
     * VULNERABLE: secret-dependent early exit. Whether this branch is
     * taken depends solely on key[0], and the resulting status_out /
     * iter_count_out values differ from the "normal" path. This leaks
     * one bit of the secret key through outputs that are supposed to be
     * public and key-independent (CWE-208 / CWE-203 / CWE-385 / CWE-200).
     */
    if (key[0] == 0) {
        /* Avoid true undefined behavior by explicitly zeroing the
         * ciphertext buffer, but this is still functionally wrong: the
         * real XOR transform is never applied on this path. */
        memset(ciphertext, 0, HLS_BLOCK_SIZE);
        *status_out = 1;
        *iter_count_out = 0;
        return;
    }

    for (int i = 0; i < HLS_BLOCK_SIZE; i++) {
        ciphertext[i] = plaintext[i] ^ key[i];
    }

    int chk = 0;
    for (int i = 0; i < HLS_BLOCK_SIZE; i++) {
        chk ^= plaintext[i];
    }
    *status_out = chk;
    *iter_count_out = HLS_BLOCK_SIZE;
}

#ifdef __cplusplus
}
#endif
